
.system-info-wrapper {
  margin-top: 16px;

  .section-title {
    color: var(--color-main-text);
    font-size: 16px;
    font-weight: 600;
    margin-bottom: 8px;
  }
}

.system-info {
  display: flex;
  flex-direction: column;
  gap: 8px;

  .system-info-item {
    display: flex;
    align-items: center;
    gap: 10px;
  }

  .system-info-label {
    font-weight: 600;
    color: var(--color-main-text);
    min-width: 120px;
  }

  .system-info-value {
    color: var(--color-text-maxcontrast);
    font-family: monospace;
  }

  .check-button {
    margin-left: 8px;
  }
}
